diff --git a/src/__tests__/object.test.ts b/src/__tests__/object.test.ts
index 23ddace3..5c31ce1c 100644
--- a/src/__tests__/object.test.ts
+++ b/src/__tests__/object.test.ts
@@ -86,22 +86,37 @@ const data = {
   points: 2314,
   unknown: 'asdf',
 };
+
+test('strip by default', () => {
+  const val = z.object({ points: z.number() }).parse(data);
+  expect(val).toEqual({ points: 2314 });
+});
+
 test('unknownkeys override', () => {
   const val = z
     .object({ points: z.number() })
     .strict()
-    .allowUnknown()
-    .stripUnknown()
+    .passthrough()
+    .strip()
     .nonstrict()
     .parse(data);

   expect(val).toEqual(data);
 });

+test('passthrough unknown', () => {
+  const val = z
+    .object({ points: z.number() })
+    .passthrough()
+    .parse(data);
+
+  expect(val).toEqual(data);
+});
+
 test('strip unknown', () => {
   const val = z
     .object({ points: z.number() })
-    .stripUnknown()
+    .strip()
     .parse(data);

   expect(val).toEqual({ points: 2314 });
